import React from 'react';
import './hero.css';

function Hero() {
  return (
    <section className="hero">
      <div className="hero-content">
        <h2>Find Your Dream Job</h2>
        <p>Search and filter jobs by category</p>
      </div>
    </section>
  );
}

export default Hero;
